import{o as n,c as i,a2 as s,j as t,t as r,p as l}from"./chunks/framework.D21_4UK8.js";const d={class:"rock-card-contact",style:{"margin-top":"2.5rem"}},c={class:"rock-copy-email-wrapper"},m=JSON.parse('{"title":"Tattoo You: User Manual","description":"","frontmatter":{},"headers":[],"relativePath":"tattoo-you.md","filePath":"tattoo-you.md"}'),u={name:"tattoo-you.md"},b=Object.assign(u,{setup(g){const o=l("Copy Email");function a(){navigator.clipboard.writeText("mainstaudiolabs@gmail.com"),o.value="Copied!",setTimeout(function(){o.value="Copy Email"},2e3)}return(h,e)=>(n(),i("div",null,[e[3]||(e[3]=s(`<h1 id="tattoo-you-user-manual" tabindex="-1">Tattoo You: User Manual <a class="header-anchor" href="#tattoo-you-user-manual" aria-label="Permalink to &quot;Tattoo You: User Manual&quot;">​</a></h1><p><strong>Version 1.0.0 · Virtual Amplifier Simulation &amp; Vintage FX Suite</strong></p><img src="/tattoo-you.png" alt="Tattoo You Plugin GUI" style="width:100%;max-width:100%;height:auto;display:block;margin:1.75rem auto;border:2px solid var(--vp-c-border);border-radius:8px;box-shadow:0 8px 24px rgba(0,0,0,0.35);"><blockquote><p><strong>Built by Stones Fans, for Guitarists:</strong><br><strong>Tattoo You</strong> was born from studying every nuance, session tape, and live track of the Rolling Stones&#39; guitar sound in obsessive detail. Created by dedicated Stones fans and seasoned guitarists, it is designed so that you can simply plug in your guitar, turn up, and immediately be immersed in the legendary 1978–1981 tone — with all the touch sensitivity, punch, and swagger of the original records.</p></blockquote><hr><h2 id="_1-design-philosophy-the-1978–1981-golden-tube-fx-era" tabindex="-1">1. Design Philosophy: The 1978–1981 Golden Tube &amp; FX Era <a class="header-anchor" href="#_1-design-philosophy-the-1978–1981-golden-tube-fx-era" aria-label="Permalink to &quot;1. Design Philosophy: The 1978–1981 Golden Tube &amp; FX Era&quot;">​</a></h2><p><strong>Tattoo You</strong> captures the definitive late &#39;70s and early &#39;80s studio and stage guitar sound of Keith Richards and the Rolling Stones. This era marked a historic sonic transition: moving from raw vintage Ampeg/Fender breakup to the high-headroom, cascaded-gain architecture of <strong>Mesa/Boogie 6L6 tube circuits</strong> paired with <strong>1x12 Electro-Voice EVM-12L speakers</strong> and front-loaded analog modulation.</p><h3 id="the-historic-timeline-1978–1981" tabindex="-1">The Historic Timeline: 1978–1981 <a class="header-anchor" href="#the-historic-timeline-1978–1981" aria-label="Permalink to &quot;The Historic Timeline: 1978–1981&quot;">​</a></h3><ol><li><p><strong>The Paris Sessions (1978 · <em>Some Girls</em> / <em>Beast of Burden</em>):</strong><br> At <em>Pathé Marconi Studios</em> in Paris, Keith introduced the iconic combination of compressed tube cleans, the liquid optical sweep of the <strong>Phase &#39;78</strong> (MXR Phase 100 style), and warm analog slapback tape echo — immortalized in the signature guitar textures of <em>&quot;Beast of Burden&quot;</em>, <em>&quot;Miss You&quot;</em>, and <em>&quot;Shattered&quot;</em>.</p></li><li><p><strong>The Tropical Overdrive Era (1979–1980 · <em>Emotional Rescue</em>):</strong><br> Continuing between Paris and <em>Compass Point Studios</em> (Nassau), the rig evolved to handle tight funk-rock dynamics (<em>&quot;Emotional Rescue&quot;</em>, <em>&quot;Dance Part 1&quot;</em>), biting reggae-rock skanks, and crunchy blues leads with unprecedented pick sensitivity and headroom.</p></li><li><p><strong>The Masterpiece Riff Power (1981 · <em>Tattoo You</em>):</strong><br> Assembled between Paris and <em>Atlantic Studios</em> (NYC), <em>Tattoo You</em> represents the zenith of this rig. The unforgettable rhythm crunch on <em>&quot;Start Me Up&quot;</em>, the driving punch of <em>&quot;Little T&amp;A&quot;</em>, the greasy groove of <em>&quot;Slave&quot;</em>, and the roaring aggression of <em>&quot;Hang Fire&quot;</em> and <em>&quot;Neighbours&quot;</em> stand as benchmark references for rock guitar tone.</p></li></ol><p>👉 <a href="/history-mesa-stones.html"><strong>&quot;The Stones Don&#39;t Pay for Amps&quot;: How the Stones Acquired the Mesa/Boogie Rigs (1978–1981) →</strong></a></p><hr><h2 id="_2-power-voicing-controls-wattage-100w-vs-60w-and-bright" tabindex="-1">2. Power &amp; Voicing Controls: WATTAGE (100W vs 60W) and BRIGHT <a class="header-anchor" href="#_2-power-voicing-controls-wattage-100w-vs-60w-and-bright" aria-label="Permalink to &quot;2. Power &amp; Voicing Controls: WATTAGE (100W vs 60W) and BRIGHT&quot;">​</a></h2><p><strong>Tattoo You</strong> features two interactive vintage toggle switches on the bottom control panel, capturing the physical and harmonic response of the &#39;78 Mark I circuit:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Control</th><th style="text-align:left;">Position</th><th style="text-align:left;">Tonal Character &amp; Dynamics</th><th style="text-align:left;">Ideal Applications</th></tr></thead><tbody><tr><td style="text-align:left;"><strong><code>WATTAGE</code></strong></td><td style="text-align:left;"><strong><code>100W</code></strong> (Up)</td><td style="text-align:left;">Colossal headroom, tight and percussive low-end thump, lightning-fast transient response, and aggressive note attack without premature power-stage sag.</td><td style="text-align:left;">Huge stadium rock riffs (<em>&quot;Start Me Up&quot;</em>, <em>&quot;Little T&amp;A&quot;</em>, <em>&quot;Hang Fire&quot;</em>), heavy chord punch, and high-impact rhythm tracking.</td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;"><strong><code>60W</code></strong> (Down)</td><td style="text-align:left;">Organic power supply sag, natural power-tube compression, blooming midrange harmonics, and a spongier, touch-sensitive breakup when digging in with the pick.</td><td style="text-align:left;">Dynamic soul cleans (<em>&quot;Beast of Burden&quot;</em>, <em>&quot;Tops&quot;</em>), singing blues leads, funk comps (<em>&quot;Dance Part 1&quot;</em>), and intimate studio tracks (<em>&quot;Waiting on a Friend&quot;</em>).</td></tr><tr><td style="text-align:left;"><strong><code>BRIGHT</code></strong></td><td style="text-align:left;"><strong><code>NORMAL</code></strong> (Up)</td><td style="text-align:left;">Balanced, full-frequency response with warm midrange and smooth top-end roll-off.</td><td style="text-align:left;">Versatile all-around setting for humbuckers and heavy rock rhythm.</td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;"><strong><code>BRIGHT</code></strong> (Down)</td><td style="text-align:left;">Crystalline upper-treble chime and enhanced pick bite.</td><td style="text-align:left;">Open-G chord clarity, reggae/funk skanks, and darker pickup voicings.</td></tr></tbody></table><ul><li><strong>Interactive Control:</strong> Toggle switches using the physical lever or by simply clicking directly on the <code>100W</code>/<code>60W</code> or <code>NORMAL</code>/<code>BRIGHT</code> text labels.</li></ul><hr><h2 id="_3-3-channel-neural-amplifier-architecture" tabindex="-1">3. 3-Channel Neural Amplifier Architecture <a class="header-anchor" href="#_3-3-channel-neural-amplifier-architecture" aria-label="Permalink to &quot;3. 3-Channel Neural Amplifier Architecture&quot;">​</a></h2><p>The 3-position channel rotary selector covers the complete gain spectrum of the vintage 6L6 tube circuit:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Channel Mode</th><th style="text-align:left;">Tone Character</th><th style="text-align:left;">Ideal Applications</th></tr></thead><tbody><tr><td style="text-align:left;"><strong><code>CLEAN</code></strong></td><td style="text-align:left;">Pristine clean tone with natural tube compression, wide dynamic headroom and smooth, chimey highs.</td><td style="text-align:left;">Rhythm chord balance (<em>&quot;Beast of Burden&quot;</em>, <em>&quot;Tops&quot;</em>), funk chops, and soul ballads.</td></tr><tr><td style="text-align:left;"><strong><code>CRUNCH</code></strong></td><td style="text-align:left;">Organic edge-of-breakup with a solid low-end body, punchy mids and immediate tactile response to pick attack.</td><td style="text-align:left;">Iconic classic rock riffs (<em>&quot;Start Me Up&quot;</em>, <em>&quot;Little T&amp;A&quot;</em>, <em>&quot;Hang Fire&quot;</em>), chord crunch, and blues rhythms.</td></tr><tr><td style="text-align:left;"><strong><code>LEAD</code></strong></td><td style="text-align:left;">Searing high-gain tube saturation with rich harmonic sustain, liquid soloing feel and focused low end.</td><td style="text-align:left;">Singing lead lines, heavy rock riffs, slide guitar (<em>&quot;Slave&quot;</em>, <em>&quot;Neighbours&quot;</em>), and sustained soloing.</td></tr></tbody></table><hr><h2 id="_4-signal-flow-control-guide" tabindex="-1">4. Signal Flow &amp; Control Guide <a class="header-anchor" href="#_4-signal-flow-control-guide" aria-label="Permalink to &quot;4. Signal Flow &amp; Control Guide&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[ GUITAR INPUT ]</span></span>
<span class="line"><span>       │</span></span>
<span class="line"><span>       ▼</span></span>
<span class="line"><span> [ ADAPTIVE NOISE GATE (-58 dB) ]</span></span>
<span class="line"><span>       │</span></span>
<span class="line"><span>       ▼</span></span>
<span class="line"><span> [ PHASE &#39;78 ]  ───►  [ SLAPBACK DELAY ]</span></span>
<span class="line"><span>       │</span></span>
<span class="line"><span>       ▼</span></span>
<span class="line"><span> [ INPUT GAIN DRIVE ]</span></span>
<span class="line"><span>       │</span></span>
<span class="line"><span>       ▼</span></span>
<span class="line"><span> [ ANALOG WAVESHAPER / LIMITER (-0.1 dBFS) ]</span></span>
<span class="line"><span>       │</span></span>
<span class="line"><span>       ▼</span></span>
<span class="line"><span> [ 6L6 NEURAL PREAMP (Clean / Crunch / Lead) ]</span></span>
<span class="line"><span>       │</span></span>
<span class="line"><span>       ▼</span></span>
<span class="line"><span> [ POWER AMP TOPOLOGY (Head 100W / Combo 60W) ]</span></span>
<span class="line"><span>       │</span></span>
<span class="line"><span>       ▼</span></span>
<span class="line"><span> [ 5-BAND GRAPHIC EQ ]  ───►  [ &quot;MICK&quot; EVM-12L CABINET MODULE ]</span></span>
<span class="line"><span>       │</span></span>
<span class="line"><span>       ▼</span></span>
<span class="line"><span> [ MASTER OUTPUT ]  ───►  [ STEREO OUT ]</span></span></code></pre></div><h3 id="_1-input-stage-dynamic-protection" tabindex="-1">1. Input Stage &amp; Dynamic Protection <a class="header-anchor" href="#_1-input-stage-dynamic-protection" aria-label="Permalink to &quot;1. Input Stage &amp; Dynamic Protection&quot;">​</a></h3><ul><li><strong><code>ADAPTIVE NOISE GATE</code>:</strong> Situated at the very start of the pure instrument chain, automatically eliminating background noise, 50/60 Hz electromagnetic hum, and high-gain hiss without clipping long musical sustain (Ultra-fast 1.5ms attack, 35ms hold, 140ms natural release).</li><li><strong><code>ANALOG WAVESHAPER / SOFT CLIPPER (-0.1 dBFS)</code>:</strong> Smooth hyperbolic tangent saturation placed directly before the NAM neural engine. Guarantees 100% linear transparency for normal playing while musical soft-limiting safeguards against digital overs and neural extrapolation artifacts.</li></ul><hr><h3 id="_2-main-amplifier-controls" tabindex="-1">2. Main Amplifier Controls <a class="header-anchor" href="#_2-main-amplifier-controls" aria-label="Permalink to &quot;2. Main Amplifier Controls&quot;">​</a></h3><ul><li><strong><code>GAIN</code> (Volume / Drive):</strong> Sets input signal drive into the amplifier (<code>1.0</code> = -9 dB, <code>7.0</code> = 0 dB Unity Gain, <code>10.0</code> = +4.5 dB boost).</li><li><strong><code>VOLUME</code> (Master):</strong> Clean analog output volume (<code>1.0</code> = -36 dB bedroom volume, <code>7.0</code> = 0 dB Unity Gain, <code>10.0</code> = +18 dB boost).</li><li><strong><code>HEAD / COMBO SWITCH</code>:</strong> Selects between 100W Quad-6L6 Head and 60W Dual-6L6 Combo power section topologies.</li><li><strong><code>CHANNEL SELECTOR</code>:</strong> 3-position rotary selector switching between <code>CLEAN</code>, <code>CRUNCH</code>, and <code>LEAD</code>.</li><li><strong><code>STANDBY</code>:</strong> Instant mute toggle for guitar changes and silent pauses.</li></ul><hr><h3 id="_3-5-band-graphic-equalizer" tabindex="-1">3. 5-Band Graphic Equalizer <a class="header-anchor" href="#_3-5-band-graphic-equalizer" aria-label="Permalink to &quot;3. 5-Band Graphic Equalizer&quot;">​</a></h3><p>An authentic recreation of the classic active slider EQ with an independent <strong><code>EQ IN</code></strong> toggle and status LED:</p><ul><li><strong><code>80 Hz</code> (±12 dB):</strong> Deep sub-bass thump and cab resonance.</li><li><strong><code>240 Hz</code> (±12 dB):</strong> Low-mid boxiness control. Cutting clears mud.</li><li><strong><code>750 Hz</code> (±12 dB):</strong> Midrange punch and vocal bark.</li><li><strong><code>2200 Hz / 2.2 kHz</code> (±12 dB):</strong> The attack frequency! Delivers pick snap and chord bite.</li><li><strong><code>6600 Hz / 6.6 kHz</code> (±12 dB):</strong> Smooth air and chime characteristic of the EVM-12L speaker.</li></ul><hr><h3 id="_4-stones-78-vintage-dual-fx-suite" tabindex="-1">4. Stones &#39;78 Vintage Dual FX Suite <a class="header-anchor" href="#_4-stones-78-vintage-dual-fx-suite" aria-label="Permalink to &quot;4. Stones &#39;78 Vintage Dual FX Suite&quot;">​</a></h3><p>Integrated directly before the preamp stage, replicating the exact pedalboard signal flow used on classic records:</p><h4 id="phase-78-mxr-phase-100-style-optical-phaser" tabindex="-1"><strong>Phase &#39;78 (MXR Phase 100 Style Optical Phaser)</strong> <a class="header-anchor" href="#phase-78-mxr-phase-100-style-optical-phaser" aria-label="Permalink to &quot;**Phase &#39;78 (MXR Phase 100 Style Optical Phaser)**&quot;">​</a></h4><p><em>Recreates the signature optical modulation heard on &quot;Beast of Burden&quot;, &quot;Shattered&quot;, and &quot;Slave&quot; — providing a thick, hypnotic sweep that cut through the dual-guitar attack of Richards and Ronnie Wood.</em></p><ul><li><strong><code>PHASE &#39;78 Toggle &amp; Amber LED</code>:</strong> Activates or bypasses the phaser with 0% CPU consumption.</li><li><strong><code>SPEED</code> (<code>0.10 Hz</code> to <code>8.00 Hz</code>):</strong> Controls the LFO modulation rate with live dynamic numerical display.</li><li><strong><code>INTENS</code> (<code>0%</code> to <code>100%</code>):</strong> Controls sweep depth and vocal resonance.</li></ul><h4 id="slapback-delay-analog-tape-echo" tabindex="-1"><strong>Slapback Delay (Analog Tape Echo)</strong> <a class="header-anchor" href="#slapback-delay-analog-tape-echo" aria-label="Permalink to &quot;**Slapback Delay (Analog Tape Echo)**&quot;">​</a></h4><p><em>Recreates the warm, single-repeat analog tape slapback echo set in the classic 110ms sweet spot.</em></p><ul><li><strong><code>DELAY Toggle &amp; Red LED</code>:</strong> Activates or bypasses the tape echo.</li><li><strong><code>TIME</code> (<code>20 ms</code> to <code>300 ms</code>):</strong> Sets delay time with dynamic millisecond readout. Default: <code>110 ms</code> (Keith&#39;s classic slapback sweet spot).</li><li><strong><code>REPEATS</code> (<code>0%</code> to <code>65%</code>):</strong> Controls tape feedback.</li><li><strong><code>MIX</code> (<code>0%</code> to <code>50%</code>):</strong> Controls wet/dry balance.</li></ul><hr><h3 id="_5-1x12-hardwood-cab-lab-dual-convolution-mixer-stereo-spread" tabindex="-1">5. &quot;1x12 Hardwood Cab Lab&quot; (Dual-Convolution Mixer &amp; Stereo Spread) <a class="header-anchor" href="#_5-1x12-hardwood-cab-lab-dual-convolution-mixer-stereo-spread" aria-label="Permalink to &quot;5. &quot;1x12 Hardwood Cab Lab&quot; (Dual-Convolution Mixer &amp; Stereo Spread)&quot;">​</a></h3><p>TattooYou integrates the <strong>1x12 Hardwood Cab Lab</strong> studio overlay, powered by a parallel dual-convolution engine loaded with 24 sample-accurate impulse responses captured from an authentic <strong>EVM-12L</strong> driver in a ported solid hardwood cabinet:</p><ul><li><strong><code>CAB LAB Button &amp; Display</code>:</strong> Clicking the <code>CAB LAB</code> button or the microphone readout on the front plate opens the full-screen studio mixing console.</li><li><strong><code>MIC 1 (Direct)</code> &amp; <code>MIC 2 (Blend/Room)</code>:</strong> Two independent channels with dropdown selection across 24 official studio takes (Shure 57, Neumann 87, BassPort, and Room 3D), individual channel level faders (-24 dB to +6 dB), and polarity invert switch ($\\varnothing$ 180°).</li><li><strong><code>CAB BLEND Knob (% / Equal-Power)</code>:</strong> Smooth continuous crossfader between both microphones with equal-power loudness preservation. Accessible in the console or directly on the front panel mini-knob.</li><li><strong><code>STEREO SPREAD 3D Switch (Single-Track Stereo Secret)</code>:</strong><ul><li><strong>Mono Sum (Off):</strong> Combines both microphones in phase into the center of the track (ideal for dense rhythm mixes).</li><li><strong>Stereo Spread (On):</strong> Routes Mic 1 to the Left channel and Mic 2 to the Right channel with automatic +3 dB loudness compensation, creating <strong>colossal analog stereo width on a single DAW track without duplicating tracks</strong>.</li></ul></li><li><strong>6 Calibrated Studio Reference Presets:</strong> Instant access to industry-standard combinations (<em>Studio Standard</em>, <em>Heavy Punch</em>, <em>Live Room 3D</em>, <em>Wide Double Track</em>, etc.).</li></ul><div class="tip custom-block"><p class="custom-block-title">🎙️ MASTER AUDIO ENGINEERING &amp; MIC PLACEMENT GUIDE</p><p>Want to explore the driver acoustics of the EVM-12L, sample-accurate phase physics, and the production secret behind achieving massive stereo guitar walls on a <strong>single DAW track</strong>? 👉 <a href="/audio-mics-guide.html"><strong>Read the Complete Master Audio Engineering &amp; Mic Placement Guide (1x12 Hardwood Cab Lab) →</strong></a></p></div><hr><h2 id="_5-integrated-studio-rack-tuner" tabindex="-1">5. Integrated Studio Rack Tuner <a class="header-anchor" href="#_5-integrated-studio-rack-tuner" aria-label="Permalink to &quot;5. Integrated Studio Rack Tuner&quot;">​</a></h2><img src="/tattoo-you-tuner.png" alt="Tattoo You Integrated Studio Tuner" style="max-width:320px;width:100%;height:auto;display:block;margin:1.5rem auto;border:2px solid var(--vp-c-border);border-radius:8px;box-shadow:0 6px 18px rgba(0,0,0,0.30);"><p>Accessible via the compact <strong><code>TUNER</code></strong> button in the lower right corner, Tattoo You includes a full-featured studio chromatic tuner floating rack overlay:</p><ul><li><strong>High-Precision Vintage VU Meter:</strong> Dual-illuminated analog meter needle with a ±50 cent sweep range and a bright green center in-tune zone (±3 cents).</li><li><strong>Digital Display Center:</strong> High-contrast pitch readout featuring note name with musical octave, pitch stability filtering, exact detected frequency in Hz, and cent deviation.</li><li><strong>Dual Detection Algorithms (<code>MPM</code> / <code>YIN</code> Switch):</strong><ul><li><strong><code>MPM</code> (McLeod Pitch Method):</strong> Ultra-fast tracking ideal for rapid stage tuning and live performance.</li><li><strong><code>YIN</code>:</strong> High-precision autocorrelation algorithm optimized for low registers and studio intonation setups.</li></ul></li><li><strong><code>MUTE</code> Switch:</strong> Silences audio output for silent on-stage tuning.</li><li><strong><code>REF A4</code> Calibration:</strong> Adjustable from 432 Hz to 448 Hz (double-click to reset to standard 440 Hz).</li><li><strong>True 0.0% CPU Standby &amp; Click-to-Close:</strong> Closes instantly via the <code>CLOSE TUNER</code> button or by simply clicking anywhere on the dimmed amplifier backdrop, automatically deactivating all DSP routines.</li></ul><hr><h2 id="_6-recommended-track-presets-dial-in-guides" tabindex="-1">6. Recommended Track Presets &amp; Dial-In Guides <a class="header-anchor" href="#_6-recommended-track-presets-dial-in-guides" aria-label="Permalink to &quot;6. Recommended Track Presets &amp; Dial-In Guides&quot;">​</a></h2><h3 id="preset-1-start-me-up-tattoo-you-crunch-riff-power" tabindex="-1">Preset 1: &quot;Start Me Up&quot; / &quot;Tattoo You Crunch&quot; (Riff Power) <a class="header-anchor" href="#preset-1-start-me-up-tattoo-you-crunch-riff-power" aria-label="Permalink to &quot;Preset 1: &quot;Start Me Up&quot; / &quot;Tattoo You Crunch&quot; (Riff Power)&quot;">​</a></h3><ul><li><strong>Power Amp:</strong> <code>HEAD</code> (100W)</li><li><strong>Channel:</strong> <code>CRUNCH</code></li><li><strong>Gain:</strong> <code>7.5</code> | <strong>Volume:</strong> <code>7.5</code></li><li><strong>5-Band Graphic EQ:</strong> <code>80Hz: +1.5dB</code> | <code>240Hz: -3.0dB</code> | <code>750Hz: +2.5dB</code> | <code>2.2kHz: +4.0dB</code> | <code>6.6kHz: +2.0dB</code></li><li><strong>Phase &#39;78:</strong> <code>OFF</code></li><li><strong>Slapback Delay:</strong> <code>OFF</code> (or <code>ON</code> with Mix @ <code>12%</code> for subtle studio room depth)</li><li><strong>MICK:</strong> <code>SM57 Warm</code> (or <code>SM57 SweetSpot</code>)</li></ul><h3 id="preset-2-beast-of-burden-shattered-the-signature-liquid-phase-clean" tabindex="-1">Preset 2: &quot;Beast of Burden&quot; / &quot;Shattered&quot; (The Signature Liquid Phase Clean) <a class="header-anchor" href="#preset-2-beast-of-burden-shattered-the-signature-liquid-phase-clean" aria-label="Permalink to &quot;Preset 2: &quot;Beast of Burden&quot; / &quot;Shattered&quot; (The Signature Liquid Phase Clean)&quot;">​</a></h3><ul><li><strong>Power Amp:</strong> <code>COMBO</code> (60W)</li><li><strong>Channel:</strong> <code>CLEAN</code></li><li><strong>Gain:</strong> <code>7.0</code> | <strong>Volume:</strong> <code>7.0</code></li><li><strong>5-Band Graphic EQ:</strong> <code>80Hz: 0dB</code> | <code>240Hz: -2.0dB</code> | <code>750Hz: +2.0dB</code> | <code>2.2kHz: +3.0dB</code> | <code>6.6kHz: +1.5dB</code></li><li><strong>Phase &#39;78:</strong> <code>ON</code> | Speed: <code>0.80 Hz</code> | Intensity: <code>60%</code></li><li><strong>Slapback Delay:</strong> <code>ON</code> | Time: <code>110 ms</code> | Repeats: <code>20%</code> | Mix: <code>25%</code></li><li><strong>MICK:</strong> <code>SM57 SweetSpot</code> (or <code>U87 Studio</code>)</li></ul><h3 id="preset-3-emotional-rescue-dance-part-1-funk-rock-tight-groove" tabindex="-1">Preset 3: &quot;Emotional Rescue&quot; / &quot;Dance Part 1&quot; (Funk-Rock &amp; Tight Groove) <a class="header-anchor" href="#preset-3-emotional-rescue-dance-part-1-funk-rock-tight-groove" aria-label="Permalink to &quot;Preset 3: &quot;Emotional Rescue&quot; / &quot;Dance Part 1&quot; (Funk-Rock &amp; Tight Groove)&quot;">​</a></h3><ul><li><strong>Power Amp:</strong> <code>COMBO</code> (60W)</li><li><strong>Channel:</strong> <code>CLEAN</code></li><li><strong>Gain:</strong> <code>6.5</code> | <strong>Volume:</strong> <code>8.0</code></li><li><strong>5-Band Graphic EQ:</strong> <code>80Hz: -1.0dB</code> | <code>240Hz: -4.0dB</code> | <code>750Hz: +1.0dB</code> | <code>2.2kHz: +3.5dB</code> | <code>6.6kHz: +3.0dB</code></li><li><strong>Phase &#39;78:</strong> <code>ON</code> | Speed: <code>1.20 Hz</code> | Intensity: <code>40%</code></li><li><strong>Slapback Delay:</strong> <code>OFF</code></li><li><strong>MICK:</strong> <code>SM57 Direct</code></li></ul><h3 id="preset-4-slave-neighbours-singing-tube-lead-solo" tabindex="-1">Preset 4: &quot;Slave&quot; / &quot;Neighbours&quot; (Singing Tube Lead &amp; Solo) <a class="header-anchor" href="#preset-4-slave-neighbours-singing-tube-lead-solo" aria-label="Permalink to &quot;Preset 4: &quot;Slave&quot; / &quot;Neighbours&quot; (Singing Tube Lead &amp; Solo)&quot;">​</a></h3><ul><li><strong>Power Amp:</strong> <code>HEAD</code> (100W)</li><li><strong>Channel:</strong> <code>LEAD</code></li><li><strong>Gain:</strong> <code>8.0</code> | <strong>Volume:</strong> <code>7.0</code></li><li><strong>5-Band Graphic EQ:</strong> <code>80Hz: +2.0dB</code> | <code>240Hz: -1.5dB</code> | <code>750Hz: +3.5dB</code> | <code>2.2kHz: +3.0dB</code> | <code>6.6kHz: +2.0dB</code></li><li><strong>Slapback Delay:</strong> <code>ON</code> | Time: <code>140 ms</code> | Repeats: <code>30%</code> | Mix: <code>25%</code></li><li><strong>MICK:</strong> <code>SM57 Direct</code> (or <code>U87 Studio</code>)</li></ul><hr><h2 id="_7-technical-specifications-platform-support" tabindex="-1">7. Technical Specifications &amp; Platform Support <a class="header-anchor" href="#_7-technical-specifications-platform-support" aria-label="Permalink to &quot;7. Technical Specifications &amp; Platform Support&quot;">​</a></h2><ul><li><strong>Plugin Formats:</strong> VST3 (64-bit), Standalone Application (.exe).</li><li><strong>Operating Systems:</strong><ul><li><strong>Windows:</strong> Windows 10 / Windows 11 (x64) — <em>Available Now</em>.</li><li><strong>macOS:</strong> Universal Binary (Apple Silicon M1/M2/M3/M4 &amp; Intel x64) / AU, VST3, Standalone — <em>Coming Soon</em> (Compatible with High Sierra 10.13 through macOS Sonoma/Sequoia).</li><li><strong>Linux:</strong> Ubuntu / Debian / Arch (VST3, Standalone) — <em>Coming Soon</em>.</li></ul></li><li><strong>Processing Engine:</strong> Neural Amp Modeler (NAM) WaveNet Architecture + DSP Real-time Convolution.</li><li><strong>Internal Audio Resolution:</strong> 64-bit double precision floating point processing.</li><li><strong>Sample Rates Supported:</strong> 44.1 kHz, 48 kHz, 88.2 kHz, 96 kHz, 176.4 kHz, 192 kHz.</li><li><strong>Latency:</strong> Zero latency (0 samples) for live tracking and monitoring.</li></ul><hr>`,64)),t("div",d,[e[1]||(e[1]=t("div",{class:"rock-card-contact-title"},"Questions, Feedback & Mix Sharing",-1)),e[2]||(e[2]=t("p",{class:"rock-card-contact-desc"},"Tattoo You was calibrated by guitarists for guitarists. If you have questions, feedback, or want to share tracks dialed in with Tattoo You, get in touch with us:",-1)),t("div",c,[e[0]||(e[0]=t("span",{class:"rock-email-text"},"mainstaudiolabs@gmail.com",-1)),t("button",{class:"rock-copy-btn",onClick:a},r(o.value),1)])])]))}});export{m as __pageData,b as default};
